class Solution:
    def finalState(self, windows: List[int], queries: List[int]) -> List[int]:
        qset = set(queries)
        res, seen = [], set()
        for q in reversed(queries):
            if q not in seen:
                seen.add(q); res.append(q)
        res.extend(w for w in windows if w not in qset)
        return res

