class Solution {
public:
    vector<int> finalState(vector<int>& windows, vector<int>& queries) {
        unordered_set<int> qset(queries.begin(), queries.end());
        unordered_set<int> seen;
        vector<int> res;
        for (int i = queries.size() - 1; i >= 0; i--)
            if (seen.insert(queries[i]).second) res.push_back(queries[i]);
        for (int w : windows)
            if (!qset.count(w)) res.push_back(w);
        return res;
    }
};

