class Solution {
    public int[] finalState(int[] windows, int[] queries) {
        Set<Integer> qset = new HashSet<>(), seen = new HashSet<>();
        for (int q : queries) qset.add(q);
        int[] res = new int[windows.length];
        int idx = 0;
        for (int i = queries.length - 1; i >= 0; i--)
            if (seen.add(queries[i])) res[idx++] = queries[i];
        for (int w : windows)
            if (!qset.contains(w)) res[idx++] = w;
        return res;
    }
}

