class Solution {
public:
    vector<int> finalState(vector<int>& windows, vector<int>& queries) {
        int n = windows.size();
        vector<int> nxt(n + 1), prv(n + 1);
        for (int i = 0; i <= n; i++) { nxt[i] = i + 1; prv[i] = i - 1; }
        int head = 0;
        for (int q : queries) {
            int node = q - 1;
            if (node == head) continue;
            nxt[prv[node]] = nxt[node]; prv[nxt[node]] = prv[node];
            prv[node] = -1; nxt[node] = head; prv[head] = node; head = node;
        }
        vector<int> res;
        for (int cur = head; cur < n; cur = nxt[cur]) res.push_back(windows[cur]);
        return res;
    }
};

